#!/usr/bin/env python3
"""FS3 v198 - the guns of the 3D capital ships sit on their real turrets.

    Turrets    Every beam, gun and launcher of the 24 capital ships with a
               model now sits on the matching turret of that model (POF
               TGUN, weapon class from the ship table). Number and weapons
               of the mounts are unchanged. Exception: the Lucifer's gun
               mounts carry her reactors and stay where they were.
    Facing     A turret only covers the half of space its face looks into:
               one on the back no longer fires down through the hull, one
               on the belly not upwards. Turrets on the flanks reach
               everything.
    Far flank  Turrets on the flank turned away from the player fire as
               before, but their glow and beam come out from behind the
               hull (Weg 3).
    Jump       A ship coming through her vortex (the Sathanas through the
               Knossos) shows her charge glows and muzzle orbs, cut at the
               vortex like her hull.
    Ravana     The cable bundle pulses as in the MediaVPs (animated glow,
               30 frames, models_v198.zip).

Needs v197. Edits src/50_combat.js, src/59_field3d.js, src/70_ui.js and
fieldsim.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v197 einspielen.")
if "F3D_TUR" in open("src/59_field3d.js", encoding="utf-8").read():
    sys.exit("Abbruch: v198 ist schon eingespielt.")
if "'sdsathanas'" not in open("src/59_field3d.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v197 einspielen.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
